import {
	byKind,
	declaration,
	isMcpTool,
	KINDS,
	largestFirst,
	number,
	partsOf,
	repeatedSentences,
	sum,
	tokens,
} from "./analyze.ts";
import { AGENTS, type AgentContext } from "./capture.ts";

const GENERATED =
	"<!-- Generated by `yarn run generate:prompts` (test/octocode/e2e-agent-context.test.ts); do not edit. -->";

/** A code fence longer than any backtick run in `text`, so the text cannot close it early. */
function fenced(text: string, language = "text"): string {
	const longest = Math.max(2, ...[...text.matchAll(/`+/g)].map((match) => match[0].length));
	const fence = "`".repeat(longest + 1);
	return `${fence}${language}\n${text}\n${fence}`;
}

/** The system prompt as the model reads it: the sections in order, separated by a blank line. */
export const systemText = (context: AgentContext): string =>
	context.sections.map((section) => section.text).join("\n\n");

const title = (context: AgentContext): string =>
	context.kind === "main" ? "Main session" : `Subagent: ${context.role ?? "general (no role)"}`;

const row = (...cells: string[]): string => `| ${cells.join(" | ")} |`;

export function renderSystem(context: AgentContext): string {
	const chars = systemText(context).length;
	const sections = context.sections
		.map((section) => `- \`${section.name}\`: ${number(section.text.length)} chars`)
		.join("\n");
	return `${GENERATED}\n# ${title(context)}: system prompt\n\nThe whole system prompt of the first request (${number(chars)} chars, about ${number(tokens(chars))} tokens), sections in order. Tool declarations are in [tools.md](tools.md), the conversation in [messages.md](messages.md), sizes in [sizes.md](sizes.md).\n\nSections:\n\n${sections}\n\n${fenced(systemText(context))}\n`;
}

export function renderTools(context: AgentContext): string {
	const block = (tool: AgentContext["tools"][number]): string => {
		const schema = JSON.stringify(tool.parameters);
		const chars = declaration(tool).length;
		return `### ${tool.name}\n\n${number(chars)} chars: description ${number(tool.description.length)}, parameter schema ${number(schema.length)}.\n\n${fenced(tool.description)}\n\n${fenced(JSON.stringify(tool.parameters, null, 2), "json")}`;
	};
	const native = context.tools.filter((tool) => !isMcpTool(tool.name));
	const mcp = context.tools.filter((tool) => isMcpTool(tool.name));
	const group = (heading: string, tools: typeof native): string =>
		`## ${heading} (${tools.length}; ${number(tools.reduce((total, tool) => total + declaration(tool).length, 0))} chars)\n\n${tools.length > 0 ? tools.map(block).join("\n\n") : "None."}`;
	return `${GENERATED}\n# ${title(context)}: tool declarations\n\nEvery tool of the first request with its description and parameter schema, as the model receives them. Sizes count the compact JSON declaration.\n\n${group("Native tools", native)}\n\n${group("MCP tools", mcp)}\n`;
}

export function renderMessages(context: AgentContext): string {
	const messages = context.messages
		.map(
			(message, index) =>
				`## ${index + 1}. ${message.role} (${number(message.text.length)} chars)\n\n${fenced(message.text)}`,
		)
		.join("\n\n");
	const about =
		context.kind === "main"
			? "The user's first message is a placeholder."
			: "A subagent's first message is its task as `subagents/tool.ts` builds it (`childTaskInput`, `withIdentity`): the parent's task is a placeholder, the identity and `## Report` contract are the real text.";
	return `${GENERATED}\n# ${title(context)}: messages\n\nThe conversation of the first request. ${about}\n\n${messages || "None."}\n`;
}

export function renderSizes(context: AgentContext): string {
	const parts = partsOf(context);
	const total = sum(parts);
	const table = largestFirst(parts)
		.map((part) => {
			const share = (part.chars / total) * 100;
			const cells = [
				part.kind,
				`\`${part.name}\``,
				number(part.chars),
				number(tokens(part.chars)),
				`${share.toFixed(1)}%`,
			];
			return row(...(share >= 10 ? cells.map((cell) => `**${cell}**`) : cells));
		})
		.join("\n");
	const repeats = repeatedSentences(context);
	const repeated =
		repeats.length === 0
			? "None."
			: `${number(repeats.reduce((all, repeat) => all + repeat.wasted, 0))} chars are spent on extra copies of ${repeats.length} sentences. The largest ${Math.min(30, repeats.length)}:\n\n${row("Wasted chars", "Copies", "Sentence", "Where")}\n${row("---:", "---:", "---", "---")}\n${repeats
					.slice(0, 30)
					.map((repeat) =>
						row(
							number(repeat.wasted),
							String(repeat.sources.length),
							repeat.sentence.replace(/\|/g, "\\|"),
							repeat.sources.join(", "),
						),
					)
					.join("\n")}`;
	return `${GENERATED}\n# ${title(context)}: sizes\n\nTotal ${number(total)} chars, about ${number(tokens(total))} tokens (chars / 4). Parts of 10% or more are bold.\n\n${row("Part", "Name", "Chars", "~Tokens", "Share")}\n${row("---", "---", "---:", "---:", "---:")}\n${table}\n\n## Repeated sentences (simplification candidates)\n\nSentences of 50+ characters that appear word for word in two or more places of this context. Reported only; nothing fails on them.\n\n${repeated}\n`;
}

/** `rendered/README.md`: one row per agent, each total split by part, the largest part marked. */
export function renderIndex(contexts: readonly AgentContext[]): string {
	const header = row(
		"Agent",
		"Total chars",
		"~Tokens",
		"System",
		"Native tools",
		"MCP tools",
		"Messages",
		"Largest parts",
	);
	const rows = contexts.map((context) => {
		const parts = partsOf(context);
		const sizes = KINDS.map((kind) => sum(byKind(parts, kind)));
		const largest = Math.max(...sizes);
		const cells = sizes.map((size) => (size === largest && size > 0 ? `**${number(size)}**` : number(size)));
		const top = largestFirst(parts)
			.slice(0, 3)
			.map((part) => `\`${part.name}\` ${number(part.chars)}`)
			.join(", ");
		const total = sum(parts);
		return row(`[${context.name}](${context.name}/sizes.md)`, number(total), number(tokens(total)), ...cells, top);
	});
	const agents = AGENTS.map((agent) => `- [\`${agent.name}/\`](${agent.name}/sizes.md): ${agent.about}`).join("\n");
	return `${GENERATED}\n# Rendered agent contexts\n\nThe full context each agent receives with its first model request, captured from real sessions on a scripted model by \`test/octocode/e2e-agent-context.test.ts\`. Read it to see what the model reads and what to simplify; nothing here is hand-written.\n\n${header}\n${row("---", "---:", "---:", "---:", "---:", "---:", "---:", "---")}\n${rows.join("\n")}\n\nSizes are characters of the text the model receives (tokens are chars / 4, an estimate). The largest of System, Native tools, MCP tools and Messages is bold; each agent's \`sizes.md\` ranks every section, tool and message and lists sentences repeated across its context.\n\n## Agents\n\n${agents}\n\nEach folder holds \`system.md\` (the whole system prompt), \`tools.md\` (every declaration with its parameter schema), \`messages.md\` (the conversation of the first request) and \`sizes.md\`.\n\n## What is real\n\n- The main session is the real session: the Octocode extension, the Octocode MCP server, bundled skills and a fixture \`AGENTS.md\`.\n- A subagent is started as \`subagents/tool.ts\` starts one: its role prompt, identity, read-only and lean flags reach it through \`subagentProcessEnv\`, its tools, extensions and skills through \`buildAgentArgs\`, and its first message is built by \`childTaskInput\` and \`withIdentity\`. The parent's task text and the goal are placeholders.\n- Paths, the date, platform, shell, ports and ids are replaced by fixed values so the files are the same on every machine.\n\n## Update\n\nAfter changing any prompt source, tool description or MCP preset, run \`yarn workspace @octocodeai/octocodecode run generate:prompts\`. The test fails while these files are stale.\n`;
}
